<script setup lang="ts">import { computed,ref,watch } from 'vue';import { ElDialog,ElSlider,ElSwitch,ElButton } from 'element-plus';import { useUiStore } from '../../stores/ui.store';import { useTimerStore } from '../../stores/timer.store';import { useRadioStore } from '../../stores/radio.store';import { useDeviceProfile } from '../../composables/useDeviceProfile';const ui=useUiStore(),timer=useTimerStore(),radio=useRadioStore(),{profile}=useDeviceProfile();const minutes=ref(Math.max(1,Math.round(timer.totalSeconds/60)));const width=computed(()=>profile.value.family==='phone'?'calc(100% - 24px)':profile.value.family==='tablet'?'min(620px, calc(100% - 48px))':'560px');function apply(){timer.setMinutes(minutes.value)}function applyRadioMode(){if(timer.radioMode==='stop'||timer.radioMode==='silence')radio.pause();else if(timer.radioMode==='play'&&!radio.playing){radio.current?void radio.play(radio.current):radio.surprise()}}watch(()=>timer.radioMode,()=>{if(timer.status==='running')applyRadioMode()});function action(){if(timer.status==='running')timer.pause();else if(timer.status==='paused'){timer.resume();applyRadioMode()}else{apply();timer.start();applyRadioMode()}}</script><template><ElDialog v-model="ui.timerOpen" :width="width" class="timer-dialog" align-center :show-close="true"><div class="timer-head"><div class="eyebrow">Quanto tempo vuoi tenerti?</div><div class="timer-ring" :style="{'--p':`${timer.progress*360}deg`}"><div><strong>{{timer.formatted}}</strong><span>{{timer.status==='running'?'In corso':timer.status==='paused'?'In pausa':'Per te'}}</span></div></div></div><div v-if="timer.status==='idle'||timer.status==='completed'" class="slider"><ElSlider v-model="minutes" :min="1" :max="180" :step="1" @change="apply"/><div class="presets"><button v-for="m in [5,15,25,45,60,90]" :key="m" @click="minutes=m;apply()">{{m}} min</button></div></div><div class="timer-options"><label><span>Suono alla fine</span><ElSwitch v-model="timer.endSoundEnabled"/></label><label><span>Radio durante il timer</span><select v-model="timer.radioMode"><option value="keep">Mantieni com'è</option><option value="play">Riproduci</option><option value="stop">Ferma</option><option value="silence">Silenzio</option></select></label></div><div class="timer-actions"><ElButton v-if="timer.status!=='idle'" @click="timer.reset()">Azzera</ElButton><ElButton type="primary" @click="action">{{timer.status==='running'?'Pausa':timer.status==='paused'?'Riprendi':'Avvia'}}</ElButton></div></ElDialog></template><style scoped>.timer-head{display:grid;justify-items:center;gap:1rem}.timer-ring{--p:0deg;width:min(310px,62vw);aspect-ratio:1;border-radius:50%;background:conic-gradient(var(--accent) var(--p),rgba(255,255,255,.1) 0);display:grid;place-items:center;padding:5px}.timer-ring>div{width:100%;height:100%;border-radius:50%;background:#17201b;display:grid;place-content:center;text-align:center}.timer-ring strong{font-size:clamp(2.6rem,9vw,4.6rem);font-weight:300;font-variant-numeric:tabular-nums}.timer-ring span{color:var(--text-muted);font-size:var(--font-sm)}.slider{margin:1.3rem 1rem}.presets{display:flex;gap:.4rem;flex-wrap:wrap;justify-content:center}.presets button{border:1px solid var(--glass-border);background:transparent;color:inherit;border-radius:999px;padding:.4rem .7rem}.timer-options{display:grid;gap:.75rem;margin:1.25rem 0}.timer-options label{display:flex;align-items:center;justify-content:space-between;gap:1rem}.timer-options select{background:#1c2620;color:inherit;border:1px solid var(--glass-border);border-radius:10px;padding:.5rem}.timer-actions{display:flex;justify-content:flex-end;gap:.6rem}@media(min-width:700px) and (max-width:1200px){.timer-head{padding-top:.3rem}.timer-ring{width:min(280px,38dvh)}.timer-dialog{max-height:88dvh}}</style>
